import math
import re

_UNITS = {
    1: ("s", "sec", "secs", "second", "seconds"),
    60: ("m", "min", "mins", "minute", "minutes"),
    3600: ("h", "hr", "hrs", "hour", "hours"),
    86400: ("d", "day", "days"),
    604800: ("w", "wk", "wks", "week", "weeks"),
}
_UNIT_MAP = {name: mult for mult, names in _UNITS.items() for name in names}

_NUM = r"(?:\d+(?:\.\d*)?|\.\d+)"
_COMPONENT = re.compile(r"\s*(" + _NUM + r")\s*([a-zA-Z]+)\s*")
_ISO = re.compile(
    r"P(?:(" + _NUM + r")W)?(?:(" + _NUM + r")D)?"
    r"(?:T(?:(" + _NUM + r")H)?(?:(" + _NUM + r")M)?(?:(" + _NUM + r")S)?)?"
)


def _round(total: float) -> int:
    return int(math.floor(total + 0.5))


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    if re.fullmatch(r"\d+", s):
        return int(s)

    # ISO 8601
    if s[:1] in "Pp":
        m = _ISO.fullmatch(s.upper())
        if not m or not any(m.groups()) or s.upper().endswith("T"):
            raise ValueError(f"invalid ISO duration: {text!r}")
        mults = (604800, 86400, 3600, 60, 1)
        total = sum(float(g) * k for g, k in zip(m.groups(), mults) if g)
        return _round(total)

    # Clock notation
    if ":" in s:
        parts = s.split(":")
        if len(parts) not in (2, 3) or not all(re.fullmatch(r"\d+(?:\.\d+)?", p) for p in parts):
            raise ValueError(f"invalid clock duration: {text!r}")
        vals = [float(p) for p in parts]
        if len(vals) == 2:
            vals = [0.0] + vals
        h, mi, se = vals
        if mi >= 60 or se >= 60:
            raise ValueError(f"invalid clock duration: {text!r}")
        return _round(h * 3600 + mi * 60 + se)

    # Number + unit components
    pos = 0
    total = 0.0
    found = False
    while pos < len(s):
        m = _COMPONENT.match(s, pos)
        if not m:
            raise ValueError(f"invalid duration: {text!r}")
        unit = m.group(2).lower()
        if unit not in _UNIT_MAP:
            raise ValueError(f"unknown unit {m.group(2)!r} in {text!r}")
        total += float(m.group(1)) * _UNIT_MAP[unit]
        found = True
        pos = m.end()
    if not found:
        raise ValueError(f"invalid duration: {text!r}")
    return _round(total)

